INSERT INTO "email_templates" ("id","key","name","subject","body","description","variables","isActive","createdAt","updatedAt") VALUES ('email-welcome','welcome','Selamat datang','Selamat datang di {{appName}}','<p>Halo {{name}},</p><p>Terima kasih telah mendaftarkan <strong>{{tenantName}}</strong> di {{appName}}. Lengkapi pengaturan perusahaan lalu tambahkan karyawan pertama Anda.</p><p><a href="{{loginUrl}}" class="btn">Buka {{appName}}</a></p>','Dikirim setelah pemilik perusahaan mendaftar.','[{"token":"name","label":"Nama penerima","sample":"Budi Santoso"},{"token":"tenantName","label":"Nama perusahaan","sample":"PT Maju Bersama"},{"token":"loginUrl","label":"Tautan masuk","sample":"/app/auth/login"}]'::jsonb,true,(now() at time zone 'utc'),(now() at time zone 'utc')) ON CONFLICT ("key") DO NOTHING;
INSERT INTO "email_templates" ("id","key","name","subject","body","description","variables","isActive","createdAt","updatedAt") VALUES ('email-user_invitation','user_invitation','Undangan staf platform','Undangan bergabung sebagai staf {{appName}}','<p>Halo {{name}},</p><p>{{inviterName}} mengundang Anda bergabung sebagai <strong>{{roleName}}</strong> di back-office {{appName}}.</p><p><a href="{{inviteUrl}}" class="btn">Terima undangan</a></p><p>Undangan berlaku sampai {{expiresAt}}.</p>','Undangan untuk staf back-office. Berlaku 7 hari.','[{"token":"name","label":"Nama penerima","sample":"Budi Santoso"},{"token":"inviterName","label":"Nama pengundang","sample":"Rafi"},{"token":"roleName","label":"Peran","sample":"Support"},{"token":"inviteUrl","label":"Tautan undangan","sample":"/admin/auth/accept-invite?token=abc"},{"token":"expiresAt","label":"Batas waktu","sample":"22 Oktober 2026"}]'::jsonb,true,(now() at time zone 'utc'),(now() at time zone 'utc')) ON CONFLICT ("key") DO NOTHING;
